/*
 * pwgrtest.c - host regression test for the compat getpwnam/getpwuid/
 * getgrnam/getgrgid text parsers (the Amix libc-passwd sidestep; see
 * AMIX-PORT.md "v15").  Compiles the parser code from
 * ../amixcompat.c via pwgr-shims.inc (generated by test-pwgr.sh) and
 * runs lookups against the REAL Amix 2.1c /etc/passwd and /etc/group
 * fixtures (amix-passwd.txt / amix-group.txt, pulled off the box).
 *
 * Copyright (c) 2026 Jussi Alanärä.  MIT license (see amixcompat.h).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pwd.h>
#include <grp.h>

#define getpwnam test_getpwnam
#define getpwuid test_getpwuid
#define getgrnam test_getgrnam
#define getgrgid test_getgrgid
#define fgetpwent test_fgetpwent
#define fgetgrent test_fgetgrent
#include "pwgr-shims.inc"

static int fail = 0;
#define CHECK(cond, msg) \
	if (!(cond)) { (void) printf("FAIL: %s\n", msg); fail++; }

int
main(int argc, char **argv)
{
	struct passwd *pw;
	struct group *gr;

	/* --- passwd lookups (the exact set the pkg tools use) --- */
	pw = test_getpwnam("root");
	CHECK(pw != NULL, "getpwnam root");
	CHECK(pw && pw->pw_uid == 0, "root uid 0");
	CHECK(pw && strcmp(pw->pw_dir, "/") == 0, "root dir /");
	CHECK(pw && strcmp(pw->pw_shell, "") == 0, "root empty shell");

	pw = test_getpwnam("x");	/* a user literally named "x" */
	CHECK(pw != NULL && pw->pw_uid == 91, "getpwnam x (uid 91)");

	pw = test_getpwnam("noaccess");
	CHECK(pw != NULL && pw->pw_uid == 60002, "getpwnam noaccess");

	pw = test_getpwnam("nosuchuser");
	CHECK(pw == NULL, "getpwnam miss returns NULL");

	pw = test_getpwuid(0);		/* duplicate uid-0 entries: first wins */
	CHECK(pw != NULL && strcmp(pw->pw_name, "root") == 0,
	    "getpwuid 0 -> root (first of many uid-0 entries)");

	pw = test_getpwuid(5);		/* uucp/nuucp share uid 5 */
	CHECK(pw != NULL && strcmp(pw->pw_name, "uucp") == 0,
	    "getpwuid 5 -> uucp (first match)");

	pw = test_getpwuid(44444);
	CHECK(pw == NULL, "getpwuid miss returns NULL");

	/* --- group lookups --- */
	gr = test_getgrnam("sys");
	CHECK(gr != NULL && gr->gr_gid == 3, "getgrnam sys gid 3");
	CHECK(gr && gr->gr_mem && gr->gr_mem[0] &&
	    strcmp(gr->gr_mem[0], "bin") == 0 &&
	    gr->gr_mem[2] && strcmp(gr->gr_mem[2], "adm") == 0 &&
	    gr->gr_mem[3] == NULL, "sys members bin,sys,adm");
	CHECK(gr && strcmp(gr->gr_passwd, "") == 0, "sys empty passwd field");

	gr = test_getgrnam("other");
	CHECK(gr != NULL && gr->gr_gid == 1 &&
	    (gr->gr_mem == NULL || gr->gr_mem[0] == NULL),
	    "getgrnam other (empty member list)");

	gr = test_getgrnam("lp");	/* gid 100 on Amix, not 71 */
	CHECK(gr != NULL && gr->gr_gid == 100, "getgrnam lp gid 100");

	gr = test_getgrgid(60001);
	CHECK(gr != NULL && strcmp(gr->gr_name, "nobody") == 0,
	    "getgrgid 60001 -> nobody");

	gr = test_getgrnam("nosuchgroup");
	CHECK(gr == NULL, "getgrnam miss returns NULL");

	if (fail == 0)
		(void) printf("pw/gr parser: ALL %s TESTS PASS\n", "16");
	return (fail);
}
